float hash(vec2 p){ return fract(sin(dot(p, vec2(127.1,311.7)))*43758.5453); }
float vnoise(vec2 p){ vec2 i=floor(p); vec2 f=fract(p); vec2 u=f*f*(3.0-2.0*f);
  return mix(mix(hash(i),hash(i+vec2(1.0,0.0)),u.x), mix(hash(i+vec2(0.0,1.0)),hash(i+vec2(1.0,1.0)),u.x), u.y); }
float fbm(vec2 p){ float v=0.0; float a=0.5; for(int k=0;k<5;k++){ v+=a*vnoise(p); p*=2.0; a*=0.5; } return v; }
vec4 shade(vec2 uv){
  vec2 p = (uv - 0.5) * vec2(1.7778, 1.0) * uParams.x;
  float tt = uTime * uParams.y;
  vec2 q = vec2(fbm(p + tt*0.3), fbm(p + vec2(5.2,1.3) - tt*0.2));
  vec2 r = vec2(fbm(p + 4.0*q + vec2(1.7,9.2) + tt*0.15), fbm(p + 4.0*q + vec2(8.3,2.8)));
  float f = fbm(p + 4.0*r);
  vec3 dark = vec3(0.055,0.059,0.071);
  vec3 col = mix(dark, uColorA.rgb, smoothstep(0.3, 0.85, f));
  col = mix(col, uColorB.rgb, smoothstep(0.5, 1.0, length(q)) * 0.85);
  col = mix(dark, col, 0.35 + 0.85*f);
  float vig = smoothstep(1.1, 0.15, length((uv-0.5)*vec2(1.6,1.0)));
  float band = smoothstep(0.42, 0.0, abs(uv.y - 0.55));
  col *= mix(0.45, 1.0, vig) * mix(1.0, 0.6, band * 0.6);
  return vec4(col, 1.0);
}
